          "main.go": "package main\n\nimport \"fmt\"\n\nfunc main() {\n\tfmt.Println(7 / 2)       // 整数相除，去掉小数部分，得到 3。\n\tfmt.Println(7 % 2)       // 7 = 3×2 + 1，余数是 1。\n\tfmt.Println(7.0 / 2.0)   // 本行使用带小数点的数，结果为 3.5。\n\tfmt.Println((2 + 3) * 4) // 括号里的加法先执行，再乘 4。\n\tfmt.Println(60 >= 60)    // 等于也满足 >=，因此是 true。\n}\n"
