          "main.go": "package main\n\nimport \"fmt\"\n\nfunc main() {\n\tscore := 60\n\t// 先计算比较结果；只有为 true 时才进入这对花括号。\n\tif score >= 60 {\n\t\tfmt.Println(\"及格\")\n\t} else {\n\t\t// 同一次判断不满足条件时，执行另一边。\n\t\tfmt.Println(\"未及格\")\n\t}\n}\n"
