          "main.go": "package main\n\nimport \"fmt\"\n\n// Add 接收两个整数，返回一个整数；定义本身不会启动计算。\nfunc Add(a int, b int) int {\n\treturn a + b // 把计算结果交回调用处，而不是直接打印。\n}\n\nfunc main() {\n\t// 2 传给 a、3 传给 b；调用结束后 result 接住返回的 5。\n\tresult := Add(2, 3)\n\tfmt.Println(result)\n}\n"
