          "main.go": "package main\n\nimport \"fmt\"\n\n// Factorial 只在本课的小非负整数范围内计算阶乘。\nfunc Factorial(n int) int {\n\tif n <= 1 {\n\t\treturn 1 // 停止条件：0! 与 1! 都是 1，不再调用自己。\n\t}\n\t// 先取得较小问题的结果，再乘当前 n；每次 n 都减少 1。\n\treturn n * Factorial(n-1)\n}\n\nfunc main() {\n\tfmt.Println(Factorial(5)) // 计算 5×4×3×2×1。\n}\n"
