          "main.go": "package main\n\nimport \"fmt\"\n\nfunc main() {\n\tcounts := map[string]int{} // 创建可写的表：文字是键，整数是值。\n\tcounts[\"go\"]++             // 没写入过的键读到 0，加 1 后写回 1。\n\tcounts[\"go\"]++             // 再读到 1，更新为 2。\n\t// 两个结果分别表示计数和“这个键是否真的存在”。\n\tvalue, exists := counts[\"web\"]\n\tfmt.Println(counts[\"go\"])\n\tfmt.Println(value, exists)\n}\n"
