          "main.go": "package main\n\nimport \"fmt\"\n\ntype Problem struct {\n\tTitle  string\n\tSolved bool\n}\n\n// 函数名前的 (p *Problem) 是接收者，指定这次要修改哪条记录。\nfunc (p *Problem) MarkSolved() {\n\tp.Solved = true // p 是指针，写入的是原记录的字段。\n}\n\nfunc main() {\n\tp := Problem{Title: \"Two Sum\"}\n\tp.MarkSolved() // 对可取地址的 p，Go 在这里自动使用它的地址。\n\tfmt.Println(p.Solved)\n}\n"
