          "main.go": "package main\n\nimport (\n\t\"fmt\"\n\t\"net/http\"\n)\n\nfunc main() {\n\t// NewRequest 只整理请求数据；这里没有启动服务，也没有发送请求。\n\t// GET 是方法，完整 URL 是目标地址，nil 表示本例没有请求正文。\n\treq, err := http.NewRequest(\"GET\", \"http://127.0.0.1:8080/hello?name=Go\", nil)\n\tif err != nil {\n\t\tfmt.Println(\"请求地址不合法：\", err)\n\t\treturn\n\t}\n\n\t// req 保存请求；URL 保存拆好的地址，Path 只取路径部分。\n\tfmt.Println(req.Method, req.URL.Path)\n\t// Query 得到查询参数，Get(\"name\") 读取 name 对应的字符串。\n\tfmt.Println(req.URL.Query().Get(\"name\"))\n}\n"
