          "main.go": "package main\n\nimport \"fmt\"\n\nfunc main() {\n\tpage, limit := 2, 20\n\t// 给page上限，避免任意巨大整数在后面乘法中溢出。\n\tif page < 1 || page > 1000000 || limit < 1 || limit > 100 {\n\t\tfmt.Println(\"非法分页\")\n\t\treturn\n\t}\n\toffset := (page - 1) * limit // 本规则下最大不足一亿，在32位int范围内。\n\tfmt.Println(offset)\n}\n"
