          "main.go": "package main\n\nimport (\n\t\"fmt\"\n\t\"sync\"\n)\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tvar mu sync.Mutex\n\tcount := 0\n\tfor i := 0; i < 100; i++ {\n\t\twg.Add(1)\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tmu.Lock() // 所有任务用同一把锁保护同一个count。\n\t\t\tcount++ // 读、改、写均在锁内，而不是只锁住写回。\n\t\t\tmu.Unlock()\n\t\t}()\n\t}\n\twg.Wait() // 完成后不再有任务写count，主函数才读取最终值。\n\tfmt.Println(count)\n}\n"
