          "index.html": "<!doctype html>\n<html lang=\"zh-CN\">\n<head><meta charset=\"UTF-8\"><title>作用域</title></head>\n<body>\n<p>打开Console看结果。</p>\n<script>\n// 这是函数外的变量。\nlet count = 3;\n// value 是本次调用的局部参数；改 value 不直接改外面的 count。\nfunction change(value) { value = 9; return value; }\nconsole.log(change(count));\n// 外部没有重新赋值，因此这里仍读取 3。\nconsole.log(count);\n</script>\n</body>\n</html>"
